export function serverModeValues(): ServerMode[] {
  return [ServerMode.LETS_ENCRYPT, ServerMode.CERT, ServerMode.NO_TLS];
}
export function serverModeStringValues(): string[] {
  return ["lets-encrypt", "cert", "no-tls"];
}
export function parseServerMode(s: string): ServerMode {
  if (!s) {
    return ServerMode.UNDEFINED;
  }
  switch (s.toLowerCase()) {
    case "lets-encrypt":
      return ServerMode.LETS_ENCRYPT;
    case "cert":
      return ServerMode.CERT;
    case "no-tls":
      return ServerMode.NO_TLS;
    default:
      throw newErrMissingInvalidData(undefined, `Invalid servermode: ${s}`);
  }
}
export function parseServerModes(s: string): ServerMode[] {
  if (!s) {
    return [];
  }
  return s
    .split(",")
    .map((part) => part.trim())
    .filter((part) => part !== "")
    .map((part) => parseServerMode(part));
}
export function serverModeToString(v: ServerMode): string {
  switch (v) {
    case ServerMode.LETS_ENCRYPT:
      return "lets-encrypt";
    case ServerMode.CERT:
      return "cert";
    case ServerMode.NO_TLS:
      return "no-tls";
    default:
      return "";
  }
}

