// Merge: Config
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeConfig(dst: Config, src: Config): void {
  if (dst.httpListen === "") {
    dst.httpListen = src.httpListen;
  }
  if (dst.httpsListen === "") {
    dst.httpsListen = src.httpsListen;
  }
  if (!dst.tlsCert && src.tlsCert) {
    dst.tlsCert = src.tlsCert;
  }
  if (dst.serverMode === 0) {
    dst.serverMode = src.serverMode;
  }
  if (dst.fqdn === "") {
    dst.fqdn = src.fqdn;
  }
  if (dst.letsEncryptEmail === "") {
    dst.letsEncryptEmail = src.letsEncryptEmail;
  }
  if (dst.staticFilePaths.length === 0) {
    dst.staticFilePaths = src.staticFilePaths;
  }
}
// ============================================================
// Merge: State
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeState(dst: State, src: State): void {
  if (dst.lastUpdated === 0n) {
    dst.lastUpdated = src.lastUpdated;
  }
  if (!dst.cert && src.cert) {
    dst.cert = src.cert;
  } else if (dst.cert && src.cert) {
    mergeCertState(dst.cert, src.cert);
  }
}
// ============================================================
// Merge: CertState
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeCertState(dst: CertState, src: CertState): void {
  if (dst.isDir === false) {
    dst.isDir = src.isDir;
  }
  if (dst.modTime === 0n) {
    dst.modTime = src.modTime;
  }
  if (dst.value.length === 0) {
    dst.value = src.value;
  }
}
// ============================================================
// Merge: StaticFilePath
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeStaticFilePath(
  dst: StaticFilePath,
  src: StaticFilePath,
): void {
  if (dst.urlPath === "") {
    dst.urlPath = src.urlPath;
  }
  if (dst.directory === "") {
    dst.directory = src.directory;
  }
}
