// Merge: HealthCheckResponse
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeHealthCheckResponse(
  dst: HealthCheckResponse,
  src: HealthCheckResponse,
): void {
  if (dst.status === "") {
    dst.status = src.status;
  }
  if (dst.time === 0n) {
    dst.time = src.time;
  }
}
